use glam::DVec3 as V;use ingetrazo_core::{image_plane::ImagePlane,groups::Group,scene::SelectionItem,math::Ray};use ingetrazo_gui::IngeTrazoApp;use ingetrazo_tools::base::{ToolContext,ToolType};
fn ctx(p:V)->ToolContext{ToolContext::new(p,Ray::new(V::new(0.5,0.5,10.),-V::Z))}fn state(a:&IngeTrazoApp)->serde_json::Value{serde_json::json!({"frame":[a.scene.image_planes[0].origin,a.scene.image_planes[0].u,a.scene.image_planes[0].v],"active":a.active_tool_type==ToolType::Rotate&&a.active_tool.snap_anchor().is_some(),"editing":!a.component_edit_stack.is_empty(),"undo":a.undo_stack.len()})}
fn main(){let mut rows=serde_json::Map::new();for context_kind in ["plain","component","folded","nested","nested_folded"]{for case in ["finish_live","cancel_then_finish"]{let mut a=IngeTrazoApp::new();a.system_clipboard=None;let mut group=Group::new("Leaf");group.mesh.add_vertex(V::ZERO);group.mesh.add_vertex(V::X);group.mesh.add_vertex(V::Y);group.mesh.add_face(vec![0,1,2],vec![]);let leaf=group.id;if context_kind.starts_with("nested"){let mut outer=Group::new("Outer");outer.children.push(group);a.scene.groups.push(outer);let id=a.scene.groups[0].id;a.scene.make_component(id).unwrap();}else{a.scene.groups.push(group);if context_kind!="plain"{a.scene.make_component(leaf).unwrap();}}a.scene.image_planes.push(ImagePlane::new("scan",V::new(0.125,-1.25,2.5),V::X*2.,V::Y*2.));a.scene.select(SelectionItem::Group(0));a.begin_component_edit();if context_kind.starts_with("nested"){a.scene.clear_selection();a.scene.select(SelectionItem::Group(0));a.begin_component_edit();}if ["folded","nested_folded"].contains(&context_kind){a.save_undo_state();a.scene.mesh.vertices[0].position+=V::Z*0.25;a.scene.bump_version();}a.scene.clear_selection();a.scene.select(SelectionItem::ImagePlane(0));a.set_tool(ToolType::Rotate);let mut states=vec![state(&a)];a.dispatch_tool_click(&ctx(V::ZERO));a.dispatch_tool_click(&ctx(V::X));a.dispatch_tool_move(&ctx(V::Y));a.dispatch_tool_move(&ctx(V::X+V::Y));states.push(state(&a));if case=="cancel_then_finish"{a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));}while !a.component_edit_stack.is_empty(){a.finish_component_edit();}states.push(state(&a));if case=="finish_live"{a.dispatch_tool_move(&ctx(V::X-V::Y));states.push(state(&a));a.dispatch_tool_click(&ctx(-V::Y));states.push(state(&a));a.undo();states.push(state(&a));a.redo();states.push(state(&a));}a.active_tool.on_cancel(&mut a.scene);states.push(state(&a));rows.insert(format!("{context_kind}:{case}"),serde_json::json!(states));}}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
